-- Generated by scripts/generate-value-sql.js from the catalog JSON files - do not edit by hand.
-- Run in SSMS AS THE NLSQL READ-ONLY LOGIN, in the warehouse database. Read-only (one #temp table).
-- Then save the result grid as CSV and run: node scripts/build-value-index.js --input <file.csv>
-- The result is real warehouse data (names of customers, suppliers, staff): keep the CSV and
-- catalog/values.json out of git.
-- 240 columns; columns with more than 5000 distinct values are skipped (see Messages).
SET NOCOUNT ON;
IF OBJECT_ID(N'tempdb..#nlsql_values') IS NOT NULL DROP TABLE #nlsql_values;
CREATE TABLE #nlsql_values (entity nvarchar(128), [column] nvarchar(128), value nvarchar(400), [rows] bigint, key_value nvarchar(100));
BEGIN TRY
  IF (SELECT COUNT(DISTINCT [ProductName]) FROM [BOM].[BOMDetails]) <= 5000
    INSERT INTO #nlsql_values (entity, [column], value, [rows], key_value)
    SELECT N'BOMDetails', N'ProductName', CAST([ProductName] AS nvarchar(400)), COUNT(*), CAST(NULL AS nvarchar(100))
    FROM [BOM].[BOMDetails] WHERE [ProductName] IS NOT NULL AND LTRIM(RTRIM(CAST([ProductName] AS nvarchar(400)))) <> N'' GROUP BY [ProductName];
  ELSE PRINT N'skipped (more than 5000 distinct values): BOMDetails.ProductName';
END TRY
BEGIN CATCH PRINT N'FAILED BOMDetails.ProductName: ' + ERROR_MESSAGE(); END CATCH
